//! 🗺️ A declared variant mapper owns its actual operation and outcome instead of an opaque fn(T)->U callback.
use super::*;
pub trait OwnedReceivingMap<T:RetireOwned>:Send+'static{type Output:RetireOwned;fn map_demand(input:&T)->Result<RetirementDemand,ValueError>;fn map_into(input:&mut Option<T>,output:&mut Option<Self::Output>,g:RetainedCloneGrant)->RetainedWorkOutcome<RetainedCloneProgress>;}
pub struct MappedReceiving<T:DslOwnedReceivingField,M:OwnedReceivingMap<T>>{current:OwnedSlot<FieldValue>,child_output:OwnedSlot<T>,output:OwnedSlot<M::Output>,child:OwnedReceivingSlot<T>,phase:u8,closing:bool,failed:bool,kind:std::marker::PhantomData<M>}
impl<T:DslOwnedReceivingField,M:OwnedReceivingMap<T>>MappedReceiving<T,M>{pub fn new()->Self{Self{current:Default::default(),child_output:Default::default(),output:Default::default(),child:OwnedReceivingSlot::new(),phase:0,closing:false,failed:false,kind:Default::default()}}fn selected(&mut self,source:&mut Option<FieldValue>,native:&mut NativeDecodeControl<'_>,body:usize,g:RetainedCloneGrant)->RetainedWorkOutcome<RetainedCloneProgress,OriginalReceivingPrimary>{if self.failed||self.closing{return RetainedWorkOutcome{result:Err(invariant().into()),work:0}}if self.phase==6{return RetainedWorkOutcome{result:Ok(Default::default()),work:0}}let d=match self.demands(source,body){Ok(d)=>d,Err(e)=>return RetainedWorkOutcome{result:Err(e.into()),work:0}};if !funds(g,d){return RetainedWorkOutcome{result:Ok(Default::default()),work:0}}match self.phase{1 if !self.child.is_ready()=>return self.child.step(&mut self.current.value,native,body,child_grant(g)),2 if self.child_output.value.is_none()=>return normal(self.child.take_into(&mut self.child_output.value,child_grant(g))),3 if !self.child.terminal_is_empty()=>return post_child_close(self.child.close_step(child_grant(g)),native,g),4 if self.output.value.is_none()=>{if let Err(e)=storage::capacity(native,d.capacity_bytes){return RetainedWorkOutcome{result:Err(e.into()),work:0}}let turn=M::map_into(&mut self.child_output.value,&mut self.output.value,g);return physical(native.receive_retained_work(g,RetainedWorkOutcome{result:turn.result.map(RetainedCloneStep::Progress),work:turn.work}))},5 if !self.current.terminal_is_empty()=>return close_source(&mut self.current,native,g),_=>{}}if let Err(e)=native.checkpoint(){return RetainedWorkOutcome{result:Err(e.into()),work:0}}let result=(||{match self.phase{0=>{if source.is_none(){return Err(invalid())}*self.current.value=source.take();self.phase=1;},1=>self.phase=2,2=>self.phase=3,3=>self.phase=4,4=>self.phase=5,5=>self.phase=6,_=>return Err(invariant())}Ok(receipt(d))})();RetainedWorkOutcome{result:result.map_err(|e|OriginalReceivingPrimary::from(e.with_retained_progress(receipt(metadata::<()>())))),work:1}}}
impl<T:DslOwnedReceivingField,M:OwnedReceivingMap<T>>OwnedFieldReceiving<M::Output>for MappedReceiving<T,M>{
 fn demands(&self,_:&Option<FieldValue>,body:usize)->Result<RetirementDemand,ValueError>{if self.closing||self.failed{return Err(invariant())}match self.phase{1 if !self.child.is_ready()=>self.child.demands(&self.current.value,body).and_then(nested),2 if self.child_output.value.is_none()=>nested(nested(metadata::<T>())?),3 if !self.child.terminal_is_empty()=>self.child.close_demands(body).and_then(nested),4 if self.output.value.is_none()=>M::map_demand(self.child_output.value.as_ref().ok_or_else(invariant)?),5 if !self.current.terminal_is_empty()=>self.current.close_demands(body),6=>Ok(Default::default()),_=>Ok(metadata::<()>())}}
 fn step(&mut self,source:&mut Option<FieldValue>,native:&mut NativeDecodeControl<'_>,body:usize,g:RetainedCloneGrant)->RetainedWorkOutcome<RetainedCloneProgress,OriginalReceivingPrimary>{let turn=self.selected(source,native,body,g);if turn.result.is_err()&&turn.work>0{self.failed=true}turn}
 fn is_ready(&self)->bool{!self.closing&&!self.failed&&self.phase==6&&self.output.value.is_some()}
 fn take_into(&mut self,output:&mut Option<M::Output>,g:RetainedCloneGrant)->RetainedWorkOutcome<RetainedCloneProgress>{if !self.is_ready(){return RetainedWorkOutcome{result:Err(invariant()),work:0}}move_into(&mut self.output.value,output,g)}
 fn close_demands(&self,body:usize)->Result<RetirementDemand,ValueError>{if self.terminal_is_empty(){return Ok(Default::default())}if !self.closing{return Ok(metadata::<()>())}if !self.child.terminal_is_empty(){return self.child.close_demands(body).and_then(nested)}if !self.current.terminal_is_empty(){return self.current.close_demands(body)}if !self.child_output.terminal_is_empty(){return self.child_output.close_demands(body)}self.output.close_demands(body)}
 fn close_step(&mut self,g:RetainedCloneGrant)->RetainedWorkOutcome<RetainedCloneProgress>{if self.terminal_is_empty(){return RetainedWorkOutcome{result:Ok(Default::default()),work:0}}let d=match self.close_demands(g.maximum_copy_bytes){Ok(d)=>d,Err(e)=>return RetainedWorkOutcome{result:Err(e),work:0}};if !funds(g,d){return RetainedWorkOutcome{result:Ok(Default::default()),work:0}}if !self.closing{self.closing=true;return RetainedWorkOutcome{result:Ok(receipt(d)),work:1}}if !self.child.terminal_is_empty(){return self.child.close_step(child_grant(g))}if !self.current.terminal_is_empty(){return self.current.close_step(g)}if !self.child_output.terminal_is_empty(){return self.child_output.close_step(g)}self.output.close_step(g)}
 fn terminal_is_empty(&self)->bool{self.child.terminal_is_empty()&&self.current.terminal_is_empty()&&self.child_output.terminal_is_empty()&&self.output.terminal_is_empty()}
}
